import { createRequire } from 'module'
const require = createRequire(import.meta.url)
const yargs = require('./index.js')

// Same setup as in the bug report: a repeatable option with nargs: 1
const argv = yargs
  .option('header', {
    requiresArg: true,
    array: true,
    nargs: 1
  })
  .parse(['--header', 'foo', 'bar'])

const header = JSON.stringify(argv.header)
const rest = JSON.stringify(argv._)

if (header === '["foo"]' && rest === '["bar"]') {
  console.log('OK: nargs: 1 is respected for the array option')
  process.exitCode = 0
} else {
  console.log(
    `WHOBROKEIT_BUG: expected header=["foo"] and _=["bar"], but got header=${header} and _=${rest}`
  )
  process.exitCode = 1
}
